-- The wheel of the day. Each turn is a day: the twins must be where the inscription says for that day.
CDV.WHEEL_DIST = 400
local wheelBusy = false
local LAMPS = { { 126464, -23296, 62464 }, { 127488, -23296, 62464 }, { 128512, -23296, 62464 } }
local function twinAt(name)
    local b = CDV.M(name)
    if b == nil or not b:GetValid() then return -1, -1 end
    local p = b:GetPosition()
    return math.floor(p.x / 1024), math.floor(p.z / 1024)
end
local function twinOn(name, sx, sz)
    local x, z = twinAt(name)
    return x == sx and z == sz
end
local function dayRight(day)
    if day == 1 then return twinOn("statua_castore", 122, 57) and twinOn("statua_polluce", 126, 57) end
    if day == 2 then return twinOn("statua_polluce", 122, 57) and twinOn("statua_castore", 126, 57) end
    return (twinOn("statua_castore", 123, 59) and twinOn("statua_polluce", 125, 59))
        or (twinOn("statua_castore", 125, 59) and twinOn("statua_polluce", 123, 59))
end
local function turnWheel(fn)
    local m = CDV.M("ruota_giorno")
    local p, r0 = m:GetPosition(), m:GetRotation()
    local a = math.rad(r0.y)
    local lp = Lara:GetPosition()
    Lara:SetPosition(TEN.Vec3(math.floor(p.x - math.sin(a) * CDV.WHEEL_DIST), lp.y, math.floor(p.z - math.cos(a) * CDV.WHEEL_DIST)), false)
    Lara:SetRotation(TEN.Rotation(0, r0.y, 0))
    Lara:SetAnim(470)              -- LA_VALVE_TURN, as at the winch of Marinello
    Lara:SetState(40)
    local f = 0
    local function step()
        f = f + 1
        if f > 40 and f <= 150 then
            local t = (f - 40) / 110
            pcall(function() m:SetRotation(TEN.Rotation(r0.x, r0.y, (r0.z + 180 * t) % 360)) end)
        end
        if f < 220 and (f < 152 or Lara:GetAnim() == 470) then CDV.After(1, step); return end
        pcall(function() m:SetRotation(TEN.Rotation(r0.x, r0.y, (r0.z + 180) % 360)) end)
        fn()
    end
    CDV.After(1, step)
end
CDV.Loop(function()
    local day = CDV.Flag("giorno") or 1
    for i = 1, math.min(day - 1, 3) do                    -- a green lamp over the gate for every day that went right
        local q = LAMPS[i]
        TEN.Effects.EmitLight(TEN.Vec3(q[1], q[2], q[3]), TEN.Color(40, 220, 90), 9, false, "cdv_giorno_" .. i)
    end
    if wheelBusy or CDV.Flag("gemelli_ok") then return end
    local m = CDV.M("ruota_giorno")
    if m == nil or not m:GetValid() then return end
    local q = m:GetPosition()
    if not CDV.Near(q.x, q.y + 620, q.z - CDV.WHEEL_DIST, 420, 300) then return end
    if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) or Lara:GetState() ~= 2 then return end
    if not CDV.HandsFree() then CDV.Armed() return end
    if not CDV.Has(ID.PUZZLE_ITEM7) then
        CDV.Say("The wheel will not turn. At its centre, an empty star-shaped socket.", 5)
        return
    end
    wheelBusy = true
    CDV.Log("RUOTA giorno " .. day)
    turnWheel(function()
        wheelBusy = false
        if dayRight(day) then
            CDV.Flag("giorno", day + 1)
            CDV.Sfx(114)
            CDV.Glow({ LAMPS[math.min(day, 3)] }, 60, 255, 90, 60, 30)
            CDV.Log("RUOTA giusto " .. day)
            if day >= 3 then
                CDV.Flag("gemelli_ok", true)
                CDV.Enable("porta_pozzo")
                pcall(function() TEN.Effects.MakeEarthquake(20) end)
                CDV.Cue("gemelli")
                CDV.Say("The gate at the end of the crypt opens.", 6)
            end
        else
            CDV.Log("RUOTA sbagliato " .. day)
            CDV.Flag("giorno", 1)
            CDV.Sfx(184)
            CDV.Glow({ LAMPS[1], LAMPS[2], LAMPS[3] }, 255, 40, 30, 75, 30)
            local n = CDV.Flag("gemelli_errori") or 0
            CDV.Enable("pip_e" .. (n % 6))
            CDV.Enable("pip_e" .. ((n + 1) % 6))
            CDV.Flag("gemelli_errori", n + 2)
            if day > 1 then CDV.Say("The lights over the gate go out.", 5) end
        end
    end)
end)

